import math

def calculate_K(n):
    # Check for potential division by zero, although for integer n >= 0, 2n - 1 = 0 only if n = 0.5
    if 2 * n - 1 == 0:
        return None # Should not happen for integer n

    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    result = numerator / denominator
    return result

n_values = range(8)
results = {}

for n in n_values:
    K_n = calculate_K(n)
    is_integer = K_n is not None and K_n == int(K_n)
    results[n] = {
        "K_n": K_n,
        "Is Integer": is_integer
    }

print(results)
